      ctx.save();roundPath(ctx,region.x,top,region.width,height,2);ctx.clip();
      const count=Math.max(1,Math.ceil(region.width/4));
      const step=region.width/count;
      for(let i=0;i<count;i++){
        const center=region.x+(i+.5)*step,position=(center-margin)/Math.max(1,usable+gap);
        const sweep=resting?0:Math.exp(-Math.pow((position-(progress*1.45-.2))/.13,2));
        const openness=1-sweep*.74;
        const half=Math.max(.3,(step-Math.min(1.2,step*.3))*.5*openness);
        const tilt=sweep*Math.min(1.6,step*.3);
        ctx.beginPath();ctx.moveTo(center-half+tilt,top);ctx.lineTo(center+half+tilt,top);
        ctx.lineTo(center+half-tilt,top+height);ctx.lineTo(center-half-tilt,top+height);ctx.closePath();
        ctx.fillStyle=`rgba(${region.rgb},${.55+sweep*.4})`;ctx.fill();
        if(sweep>.2)strokeLine(ctx,center-half+tilt,top,center-half-tilt,top+height,`rgba(140,216,250,${sweep*.8})`,.7);
      }
