      node.dpr=Math.min(2,win.devicePixelRatio||1);
      const width=Math.round(node.w*node.dpr),height=Math.round(node.h*node.dpr);
      if(node.canvas.width!==width)node.canvas.width=width;
      if(node.canvas.height!==height)node.canvas.height=height;
