/* One metric, one scale. Interpolation stays between adjacent recorded values. */
function fansaiBoundedTrace(points) {
  if(points.length<2)return '';
  const slopes=points.slice(1).map((p,i)=>(p[1]-points[i][1])/(p[0]-points[i][0]));
  const tangents=points.map((p,i)=>{
    if(i===0)return slopes[0];
    if(i===points.length-1)return slopes[slopes.length-1];
    const before=slopes[i-1],after=slopes[i];
    return before*after<=0?0:2*before*after/(before+after);
  });
  let path='M '+points[0][0]+' '+points[0][1];
  for(let i=0;i<points.length-1;i++){
    const a=points[i],b=points[i+1],dx=(b[0]-a[0])/3,delta=slopes[i];
    const bound=m=>delta===0?0:Math.sign(delta)*Math.min(Math.abs(m),3*Math.abs(delta));
    path+=' C '+(a[0]+dx)+' '+(a[1]+bound(tangents[i])*dx)+' '+(b[0]-dx)+' '+(b[1]-bound(tangents[i+1])*dx)+' '+b[0]+' '+b[1];
  }
  return path;
}

