/* Vector glass comparison. Face heights, including the excess cap, share one scale. */
function fansaiRoiGlassGeometry(revenue,cost) {
  const valid=Number.isFinite(revenue)&&Number.isFinite(cost)&&revenue>=0&&cost>=0;
  const maximum=valid?Math.max(revenue,cost):0;
  const height=value=>maximum>0?value/maximum*130:0;
  const shared=valid?Math.min(revenue,cost):0;
  return {
    valid,maximum,baseline:161,bodyHeight:height(shared),
    revenueHeight:valid?height(revenue):0,costHeight:valid?height(cost):0,
    revenueCapHeight:valid?height(Math.max(0,revenue-cost)):0,
    costCapHeight:valid?height(Math.max(0,cost-revenue)):0,
    sign:!valid?'unknown':revenue===cost?'balanced':revenue>cost?'gain':'loss'
  };
}

function FansaiRoiGlass({revenue,cost,profit,signature=''}) {
  const h=gxEl,root=ju.useRef(null),uid=ju.useId().replace(/[^a-zA-Z0-9_-]/g,'');
  const g=fansaiRoiGlassGeometry(revenue,cost),prefix='rd-glass-'+uid;
  const key=[signature,revenue,cost,profit].join('|');
  const paint=name=>'url(#'+prefix+'-'+name+')';
  const description=g.sign==='unknown'?'收入或成本数据暂不可用。':g.maximum===0?'收入与成本均为零。':g.sign==='balanced'?'收入与成本相等，已达盈亏平衡。':g.sign==='gain'?'左柱为成本，右柱为收入；青蓝色上段表示收入超出成本的经营利润。':'左柱为成本，右柱为收入；橘色上段表示成本超出收入的经营亏损。';

  ju.useLayoutEffect(()=>{
    const node=root.current;if(!node)return;
    const media=matchMedia('(prefers-reduced-motion: reduce)');
    let timer=0,started=false;
    const settle=()=>{
      clearTimeout(timer);node.removeAttribute('data-enter');
      node.getAnimations?.({subtree:true}).forEach(a=>{try{a.finish();}catch{a.cancel();}});
    };
    const enter=()=>{
      const box=node.getBoundingClientRect();
      if(started||document.hidden||box.bottom<=0||box.top>=window.innerHeight)return;
      started=true;
      if(media.matches||!g.valid||g.maximum===0){settle();return;}
      node.setAttribute('data-enter','true');timer=setTimeout(settle,1020);
    };
    const visibility=()=>{if(document.hidden)settle();else enter();};
    const preference=()=>{if(media.matches)settle();};
    const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{
      if(entries[0]?.isIntersecting)enter();else if(started)settle();
    },{threshold:.1}):null;
    settle();observer?.observe(node);enter();
    document.addEventListener('visibilitychange',visibility);media.addEventListener('change',preference);
    return()=>{settle();observer?.disconnect();document.removeEventListener('visibilitychange',visibility);media.removeEventListener('change',preference);};
  },[key]);

  const gradient=(name,stops,props={})=>h('linearGradient',{id:prefix+'-'+name,x1:'0%',y1:'0%',x2:'100%',y2:'0%',...props},
    stops.map(([offset,color,opacity])=>h('stop',{key:offset,offset:offset+'%',stopColor:color,stopOpacity:opacity})));
  const defs=h('defs',{},
    gradient('face',[[0,'#DDF8FF',.26],[9,'#BEEBF6',.10],[27,'#6EA8B8',.035],[74,'#C9F4FB',.025],[100,'#DAFAFF',.18]]),
    gradient('side',[[0,'#BCDCE7',.03],[60,'#A5D6E1',.10],[100,'#EBFFFF',.42]]),
    gradient('top',[[0,'#D4F3FA',.38],[27,'#F6FFFF',.87],[67,'#C8F1F8',.25],[100,'#F8FFFF',.9]]),
    gradient('edge',[[0,'#F1FFFF',.84],[30,'#B4E9F7',.22],[60,'#92BBC8',.13],[100,'#DFFAFF',.76]],{x1:'0%',y1:'0%',x2:'0%',y2:'100%'}),
    gradient('facet',[[0,'#F1FFFF',.64],[100,'#C6F3FA',.05]]),
    gradient('gain',[[0,'#CFFFF2',.66],[24,'#88F5DF',.43],[64,'#88F5DF',.14],[100,'#88F5DF',.57]]),
    gradient('loss',[[0,'#FFD0A2',.78],[24,'#E38730',.54],[64,'#E38730',.24],[100,'#FFA659',.7]]));

  const prism=(x,bottom,height,tone,role)=>{
    if(!(height>0))return null;
    const w=35,dx=7,dy=6,y=bottom-height,accent=tone==='gain'?'#88F5DF':tone==='loss'?'#E38730':null;
    return h('g',{key:role+'|'+key,className:'rd-glass-prism '+(tone?'rd-glass-cap':'rd-glass-base'),
      'data-part':role,'data-height':height,style:{transformOrigin:(x+w/2)+'px '+bottom+'px'}},
      h('path',{d:`M ${x+dx} ${y-dy} V ${bottom-dy} H ${x+w+dx}`,className:'rd-glass-back-edge'}),
      h('path',{d:`M ${x+w} ${y} L ${x+w+dx} ${y-dy} V ${bottom-dy} L ${x+w} ${bottom} Z`,fill:paint(tone||'side'),className:'rd-glass-side',stroke:accent||'#DDF7FF',strokeOpacity:accent ? .56 : .42,strokeWidth:.6,strokeLinejoin:'round'}),
      h('path',{d:`M ${x} ${y} L ${x+dx} ${y-dy} H ${x+w+dx} L ${x+w} ${y} Z`,fill:paint('top'),stroke:accent||'#F2FDFF',strokeOpacity:.82,strokeWidth:.65,strokeLinejoin:'round'}),
      tone?h('path',{d:`M ${x} ${y} L ${x+dx} ${y-dy} H ${x+w+dx} L ${x+w} ${y} Z`,fill:accent,fillOpacity:.38}):null,
      h('rect',{x,y,width:w,height,rx:.8,fill:paint(tone||'face'),stroke:paint('edge'),strokeWidth:.85}),
      h('path',{d:`M ${x+.5} ${y+.6} H ${x+w-.5}`,stroke:accent||'#F0FFFF',strokeOpacity:.92,strokeWidth:.8}),
      h('path',{d:`M ${x+1.6} ${y+Math.min(height,.7)} V ${bottom-.7}`,stroke:'#E4FFFF',strokeWidth:.6,strokeOpacity:.28}),
      height>12?h('path',{d:`M ${x+1} ${bottom-1} L ${x+dx} ${bottom-dy} H ${x+w+dx-1} L ${x+w-1} ${bottom-1} Z`,fill:paint('facet'),fillOpacity:tone ? .18 : .54}):null,
      h('path',{d:`M ${x+w} ${y+.4} V ${bottom-.4}`,stroke:accent||'#E4FAFF',strokeWidth:.6,strokeOpacity:.55})
    );
  };

  const columns=[{x:13,value:cost,cap:g.costCapHeight,tone:'loss',role:'cost',label:'成本'},
    {x:80,value:revenue,cap:g.revenueCapHeight,tone:'gain',role:'revenue',label:'收入'}];
  return h('div',{ref:root,className:'rd-glass-comparison',role:'img','aria-label':description,
    'data-sign':g.sign,'data-revenue':Number.isFinite(revenue)?revenue:'','data-cost':Number.isFinite(cost)?cost:'',
    'data-maximum':g.maximum,'data-profit':Number.isFinite(profit)?profit:''},
    h('svg',{viewBox:'0 0 144 188',className:'rd-glass-svg','aria-hidden':true,focusable:'false'},defs,
      columns.map(c=>h('g',{key:c.role,'data-column':c.role},
        g.valid&&g.maximum>0?prism(c.x,g.baseline,g.bodyHeight,null,c.role+'-body'):null,
        g.valid&&c.cap>0?prism(c.x,g.baseline-g.bodyHeight,c.cap,c.tone,c.role+'-difference'):null,
        g.valid&&c.value===0?h('path',{d:`M ${c.x} ${g.baseline} H ${c.x+35}`,className:'rd-glass-zero'}):null,
        !g.valid?h('text',{x:c.x+18,y:112,textAnchor:'middle',className:'rd-glass-unknown'},'—'):null,
        h('text',{x:c.x+20,y:182,textAnchor:'middle',className:'rd-glass-label'},c.label)))
    )
  );
}

/* ROI detail: keeps the original snapshot/history, filters and navigation. */
function gxRoiNumber({value, money=false, signed=false, className='',delay=0,duration=780}) {
  const ref=ju.useRef(null),prefixRef=ju.useRef(null),previous=ju.useRef(null);
  const format=n=>!Number.isFinite(n)?'—':money?gxMoney(n,signed):n.toFixed(2);
  const paint=n=>{
    const parts=fansaiCurrencyParts(format(n));
    if(ref.current)ref.current.textContent=money?parts.number:format(n);
    if(prefixRef.current)prefixRef.current.textContent=parts.prefix;
  };
  ju.useLayoutEffect(()=>{
    const node=ref.current;if(!node)return;
    const target=Number.isFinite(value)?value:null;
    if(target===null){paint(null);previous.current=null;return;}
    const media=matchMedia('(prefers-reduced-motion: reduce)');
    let frame=0,finished=false;
    const settle=()=>{if(finished)return;finished=true;cancelAnimationFrame(frame);paint(target);previous.current=target;};
    const box=node.getBoundingClientRect();
    if(media.matches||document.hidden||box.bottom<=0||box.top>=window.innerHeight){settle();return;}
    const start=previous.current??0,at=performance.now();paint(start);
    const tick=now=>{
      if(finished)return;
      const t=Math.max(0,Math.min(1,(now-at-delay)/duration)),v=start+(target-start)*(1-Math.pow(1-t,3));
      paint(v);previous.current=v;if(t<1)frame=requestAnimationFrame(tick);else settle();
    };
    const visibility=()=>{if(document.hidden)settle();};
    const preference=()=>{if(media.matches)settle();};
    const observer=typeof IntersectionObserver==='function'?new IntersectionObserver(entries=>{
      if(entries[0]&&!entries[0].isIntersecting)settle();
    },{threshold:0}):null;
    observer?.observe(node);document.addEventListener('visibilitychange',visibility);media.addEventListener('change',preference);
    frame=requestAnimationFrame(tick);
    return()=>{finished=true;cancelAnimationFrame(frame);observer?.disconnect();document.removeEventListener('visibilitychange',visibility);media.removeEventListener('change',preference);};
  },[value,money,signed,delay,duration]);
  const parts=fansaiCurrencyParts(format(value));
  return gxEl('span',{className:className+(money?' sd-money':''),'aria-label':format(value),'data-value':Number.isFinite(value)?value:''},
    money?gxEl('span',{ref:prefixRef,className:'sd-currency-prefix','aria-hidden':true},parts.prefix):null,
    gxEl('span',{ref,className:money?'sd-money-digits':undefined,'aria-hidden':true},money?parts.number:format(value)));
}

/* The glass comparison carries geometry; the ledger keeps exact amounts legible. */
function FansaiRoiLedger({revenue,cost,profit,revenueLabel='税前收入'}) {
  return gxEl('div',{className:'rd-ledger rd-money-pair',role:'group','aria-label':'收入与成本','data-sign':profit<0?'loss':'gain'},
    [[revenueLabel,revenue,'revenue'],['总成本',cost,'cost']].map(([label,value,key])=>
      gxEl('div',{className:'rd-ledger-row',key},gxEl('span',{},label),
        gxEl(gxRoiNumber,{value,money:true,className:'rd-'+key+'-number',duration:800}))));
}

